import type { CityMap, CityMapBbox, CityMapIndexEntry } from "@/data/cityMaps";
import { createRemoteMapStore } from "@/data/remoteMapStore";
import { CITY_MAP_CACHE_KEY_PREFIX, CITY_MAP_INDEX_CACHE_KEY } from "@/data/storageKeys";
import { supabase } from "@/lib/supabase";
import AsyncStorage from "@react-native-async-storage/async-storage";

/** Where the trip map's city base maps come from: the Supabase `city_maps`
 * table (scripts/city_maps_schema.sql, rows generated by
 * scripts/build-city-map.mjs). Two steps, so adding cities never makes the
 * app download more than the one a trip needs:
 *  1. the *index* — every city's id, bbox and `updated_at`, a few hundred
 *     bytes in total, a `createRemoteMapStore` like heritage photos — used to
 *     pick the city a trip's stops fall in;
 *  2. `loadCityMap` — that one city's full row (~50–130 KB of path data),
 *     cached on the device and reused until its `updated_at` changes.
 * Loaded lazily by `useCityMapIndex`/`useCityMap`, not at startup. */

const isNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value);

function toBbox(value: unknown): CityMapBbox | null {
  if (!value || typeof value !== "object") return null;
  const { south, west, north, east } = value as Record<string, unknown>;
  if (!isNumber(south) || !isNumber(west) || !isNumber(north) || !isNumber(east)) return null;
  return { south, west, north, east };
}

const indexStore = createRemoteMapStore<CityMapIndexEntry>({
  table: "city_maps",
  keyColumn: "id",
  valueColumns: "bbox, updated_at",
  toValue: (row) => {
    const bbox = toBbox(row.bbox);
    return bbox && typeof row.updated_at === "string"
      ? { bbox, updatedAt: row.updated_at }
      : null;
  },
  cacheKey: CITY_MAP_INDEX_CACHE_KEY,
  label: "CITY MAP INDEX",
});

export const subscribeCityMapIndex = indexStore.subscribe;
export const getCityMapIndex = indexStore.getMap;
export const loadCityMapIndex = indexStore.load;

/** A `city_maps` row → `CityMap`, or null when it isn't shaped as expected
 * (the paths feed straight into the renderer, so a bad row must not reach it). */
function toCityMap(row: Record<string, unknown> | null): CityMap | null {
  if (!row) return null;
  const bbox = toBbox(row.bbox);
  const text = (value: unknown) => (typeof value === "string" ? value : "");
  if (
    !bbox ||
    typeof row.id !== "string" ||
    !isNumber(row.width) ||
    !isNumber(row.height) ||
    !Array.isArray(row.labels)
  ) {
    return null;
  }
  return {
    id: row.id,
    name: text(row.name),
    nameTr: text(row.name_tr),
    bbox,
    width: row.width,
    height: row.height,
    labels: row.labels as CityMap["labels"],
    water: text(row.water),
    green: text(row.green),
    rivers: text(row.rivers),
    canals: text(row.canals),
    minor: text(row.minor),
    major: text(row.major),
  };
}

type CachedCityMap = { updatedAt: string; map: CityMap };

// Maps already loaded this session, with the version they were loaded at.
const loaded = new Map<string, CachedCityMap>();
const inFlight = new Map<string, Promise<CityMap | null>>();

/** The map if it is already in memory at this version — lets a screen revisit
 * render it on the first frame instead of after an async cache read. */
export function peekCityMap(id: string, updatedAt: string): CityMap | null {
  const entry = loaded.get(id);
  return entry && entry.updatedAt === updatedAt ? entry.map : null;
}

async function readCachedCityMap(id: string): Promise<CachedCityMap | null> {
  try {
    const raw = await AsyncStorage.getItem(CITY_MAP_CACHE_KEY_PREFIX + id);
    if (!raw) return null;
    // The cache holds the raw `city_maps` row, so it goes through the same
    // validation as a fresh fetch.
    const parsed = JSON.parse(raw) as { updatedAt?: unknown; row?: unknown } | null;
    const map = toCityMap((parsed?.row as Record<string, unknown> | null | undefined) ?? null);
    if (!map || typeof parsed?.updatedAt !== "string") return null;
    return { updatedAt: parsed.updatedAt, map };
  } catch (e) {
    console.log("CITY MAP CACHE READ ERROR", e);
    return null;
  }
}

async function fetchCityMap(id: string, updatedAt: string): Promise<CityMap | null> {
  const cached = await readCachedCityMap(id);
  if (cached && cached.updatedAt === updatedAt) return cached.map;

  try {
    const { data, error } = await supabase.from("city_maps").select("*").eq("id", id).maybeSingle();
    if (error) throw error;
    const map = toCityMap(data as Record<string, unknown> | null);
    if (!map) return cached?.map ?? null;
    // `updatedAt` is the version the index promised; if the row moved on since,
    // the next session's index refresh will fetch it again.
    await AsyncStorage.setItem(
      CITY_MAP_CACHE_KEY_PREFIX + id,
      JSON.stringify({ updatedAt, row: data }),
    ).catch((e) => console.log("CITY MAP CACHE WRITE ERROR", e));
    return map;
  } catch (e) {
    console.log("CITY MAP FETCH ERROR", e);
    // Offline (or the fetch failed) with an older copy on the device: an
    // out-of-date map is better than none.
    return cached?.map ?? null;
  }
}

/** One city's full map at the version `updatedAt` (from the index): memory,
 * then the device cache, then Supabase. Null when it can't be had at all
 * (first use while offline, or no such row). Concurrent callers share one
 * request. */
export function loadCityMap(id: string, updatedAt: string): Promise<CityMap | null> {
  const ready = peekCityMap(id, updatedAt);
  if (ready) return Promise.resolve(ready);

  const key = `${id}@${updatedAt}`;
  let pending = inFlight.get(key);
  if (!pending) {
    pending = fetchCityMap(id, updatedAt)
      .then((map) => {
        if (map) loaded.set(id, { updatedAt, map });
        return map;
      })
      .finally(() => inFlight.delete(key));
    inFlight.set(key, pending);
  }
  return pending;
}
